// Behavior probes from the independent audit of the new site, part 5 (share image and icons
// generated by site/scripts/make-assets.mjs). Each case states, as comments, the contract it
// protects, the plausible regression that breaks it and why the implementer's tests miss it.
// None needs Chrome or the build: they call the browser-free functions of the script with
// sentinel inputs, so the answer does not depend on today's copy or today's token values.
// Run with: node --test test/*.test.mjs test/audit/*.test.mjs

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import {
  ASSETS,
  buildOgHtml,
  collectSources,
  heroContent,
  palette,
  readTokens,
} from '../../site/scripts/make-assets.mjs';
import { createLines, heroGeometry, lineCount, lineY, seededRandom } from '../../site/src/lib/flow.js';

const ROOT = dirname(dirname(dirname(fileURLToPath(import.meta.url))));
const SITE = join(ROOT, 'site');

// Every token palette() reads, each with a value no real token has.
const SENTINEL_CSS = `:root {
  --bg: #01A101; --ink: #02A202; --ink-3: #03A303; --ink-4: #04A404; --bg-sheet: #05A505;
  --rule-soft: #06A606; --e-3: 0 1px 2px #07A707; --violet: #08A808; --violet-halo: #09A909;
  --ink-on-violet: #0AAA0A;
}
[data-gx-acento="violet"] { --accent: var(--violet); --accent-ink: var(--ink-on-violet); --accent-halo: var(--violet-halo); }`;

// Locale strings with sentinel words, in the shapes Hero.astro reads them.
const SENTINEL_STRINGS = {
  heroTitle: 'Spec-driven Qtitleone\nQtitletwo',
  heroFlowBefore: 'Qbefore',
  heroFlowAfter: 'Qafter',
  heroQuickStart2Cmd: '$ gen-spec "qcard"',
  heroQuickStart2Desc: '✓ Qitemone · Qitemtwo',
  heroQuickStart4Desc: 'Qverdict. Qdropped after the first dot',
};

function sentinelSources() {
  return {
    content: heroContent(SENTINEL_STRINGS),
    palette: palette(readTokens(SENTINEL_CSS)),
    mark: 'M1 1 L2 2',
    fonts: { geist: 'data:,', mono: 'data:,', serif: 'data:,', serifItalic: 'data:,' },
  };
}

// CSS named colours (CSS Color 4), without "transparent", which only carries alpha here.
const NAMED_COLOURS = `aliceblue antiquewhite aqua aquamarine azure beige bisque black blanchedalmond blue
blueviolet brown burlywood cadetblue chartreuse chocolate coral cornflowerblue cornsilk crimson cyan
darkblue darkcyan darkgoldenrod darkgray darkgreen darkgrey darkkhaki darkmagenta darkolivegreen
darkorange darkorchid darkred darksalmon darkseagreen darkslateblue darkslategray darkslategrey
darkturquoise darkviolet deeppink deepskyblue dimgray dimgrey dodgerblue firebrick floralwhite
forestgreen fuchsia gainsboro ghostwhite gold goldenrod gray green greenyellow grey honeydew hotpink
indianred indigo ivory khaki lavender lavenderblush lawngreen lemonchiffon lightblue lightcoral
lightcyan lightgoldenrodyellow lightgray lightgreen lightgrey lightpink lightsalmon lightseagreen
lightskyblue lightslategray lightslategrey lightsteelblue lightyellow lime limegreen linen magenta
maroon mediumaquamarine mediumblue mediumorchid mediumpurple mediumseagreen mediumslateblue
mediumspringgreen mediumturquoise mediumvioletred midnightblue mintcream mistyrose moccasin
navajowhite navy oldlace olive olivedrab orange orangered orchid palegoldenrod palegreen
paleturquoise palevioletred papayawhip peachpuff peru pink plum powderblue purple rebeccapurple red
rosybrown royalblue saddlebrown salmon sandybrown seagreen seashell sienna silver skyblue slateblue
slategray slategrey snow springgreen steelblue tan teal thistle tomato turquoise violet wheat white
whitesmoke yellow yellowgreen currentcolor`.split(/\s+/);

// Contract: no literal colour in the HTML the script screenshots; every colour comes from a token
// read from the design system CSS (executor briefing, "no literal colour" rule; auditor briefing).
// Built with a palette of sentinel values, the HTML of every asset, once those values are taken
// out, carries no colour at all: no hex, no colour function, no named colour.
// Breaks when: someone writes `color: #5A5A55` (today's --ink-3) or `color: red` or an hsl()/oklch()
// in the share image or icon CSS and regenerates the assets.
// Not covered by: the implementer's colour test compares hex and rgb() literals against today's
// token values, so a literal equal to a token value passes it (the HTML is byte-identical, so the
// manifest hash passes too), and it does not look for named colours other than black and white
// or for hsl(), hwb(), lab(), lch(), oklab(), oklch() or color().
test('every colour in the asset HTML comes from the palette passed in, none is written in the script', () => {
  const sources = sentinelSources();
  const values = Object.values(sources.palette).sort((a, b) => b.length - a.length);
  for (const asset of ASSETS) {
    let html = asset.html(sources);
    for (const value of values) html = html.split(value).join('');
    assert.doesNotMatch(html, /#[0-9a-fA-F]{3,8}\b/, `${asset.file}: hex colour written in the script`);
    assert.doesNotMatch(html, /\b(rgba?|hsla?|hwb|lab|lch|oklab|oklch|color)\(/i, `${asset.file}: colour function written in the script`);
    for (const name of NAMED_COLOURS) {
      assert.doesNotMatch(html, new RegExp(`\\b${name}\\b`, 'i'), `${asset.file}: named colour ${name}`);
    }
  }
  const og = buildOgHtml(sources);
  for (const role of ['bg', 'ink', 'ink3', 'accent', 'accentHalo', 'accentInk', 'sheet', 'ruleSoft', 'shadow', 'loose', 'held']) {
    assert.ok(og.includes(sources.palette[role]), `the share image uses the ${role} token`);
  }
});

// Contract: no new text in the share image; the title, the notes, the spec card and the verdict
// come from the en.ts keys Hero.astro reads (heroTitle, heroFlowBefore, heroFlowAfter,
// heroQuickStart2Cmd, heroQuickStart2Desc, heroQuickStart4Desc). The only words of the script
// itself are the brand ("Vibeflow", the same literal as Header.astro), the domain and the
// "spec ·" prefix Hero.astro also puts on the card.
// Breaks when: the verdict chip or a note is written as a literal ("PASS", "with a spec") instead
// of the content field; after the next copy change and regeneration the image keeps the old words.
// Not covered by: the implementer's tests build the HTML from today's en.ts, whose words are the
// same as those literals, so the HTML (and its manifest hash) is byte-identical and every check
// passes; the colour test even asserts today's words ('PASS', 'with a spec') are present.
test('every visible word of the share image comes from the locale keys, the brand or the card prefix', () => {
  const html = buildOgHtml(sentinelSources());
  const text = html
    .replace(/<style>[\s\S]*?<\/style>/g, ' ')
    .replace(/<svg[\s\S]*?<\/svg>/g, ' ')
    .replace(/<br>/g, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"');
  const words = text.split(/\s+/).filter(Boolean);
  const fromKeys = ['Spec-driven', 'Qtitleone', 'Qtitletwo', 'Qbefore', 'Qafter', 'qcard', 'Qitemone', 'Qitemtwo', 'Qverdict'];
  const fromScript = ['Vibeflow', 'vibeflow.run', 'spec', '·'];
  for (const word of words) {
    assert.ok(fromKeys.includes(word) || fromScript.includes(word), `"${word}" is not from a locale key`);
  }
  for (const word of fromKeys) assert.ok(words.includes(word), `${word} is shown`);
  assert.ok(!words.includes('Qdropped'), 'the verdict is the text before the first dot');
});

// Contract: past the gate the lines of the share image run parallel to the right edge of the
// image, and they are the lines of flow.js in the still frame the hero draws (seed 7, time zero),
// not a geometry redone in the script (executor briefing, drawing rules section; auditor briefing).
// The oracle is flow.js itself: each path of the band's SVG follows lineY() for its line, spans
// the whole image width, and is flat and evenly spaced from the end of the hero ramp on.
// Breaks when: the band SVG is drawn with `flowLines(width - 4, ...)` (the prototype stopped the
// lines 4 px short), with another seed or time, or with a line formula copied into the script.
// Not covered by: the implementer's test checks flowLines() alone, and the manifest hash only
// says the HTML changed; once the assets are regenerated nothing ties the HTML to flow.js.
test('the band SVG of the share image draws the flow.js hero lines, flat and parallel to the right edge', () => {
  const og = ASSETS.find((asset) => asset.file === 'og-image.png');
  const html = buildOgHtml(collectSources(SITE));
  const svg = /<svg class="lines" viewBox="0 0 (\d+) (\d+)"[\s\S]*?<\/svg>/.exec(html);
  assert.ok(svg, 'the band SVG is in the share image');
  const W = Number(svg[1]);
  const H = Number(svg[2]);
  assert.equal(W, og.width, 'the band spans the whole image width');
  const group = /<g fill="none"[^>]*>([\s\S]*?)<\/g>/.exec(svg[0])[1];
  const paths = [...group.matchAll(/<path d="([^"]+)"\/>/g)].map(([, d]) => (
    [...d.matchAll(/[ML](-?[\d.]+) (-?[\d.]+)/g)].map(([, x, y]) => [Number(x), Number(y)])
  ));
  const lines = createLines(lineCount('hero', W), seededRandom(7));
  assert.equal(paths.length, lines.length, 'one path per hero line');
  const { rampEnd } = heroGeometry(W);
  const flatYs = paths.map((points, i) => {
    assert.equal(points[0][0], 0, `line ${i} starts at the left edge`);
    assert.equal(points.at(-1)[0], W, `line ${i} ends at the right edge`);
    for (const [x, y] of points) {
      assert.ok(Math.abs(y - lineY('hero', lines[i], x, 0, W, H)) <= 0.051, `line ${i} at x=${x} follows flow.js`);
    }
    const flat = points.filter(([x]) => x >= rampEnd);
    assert.ok(flat.length > 50, `line ${i} has a stretch past the gate`);
    for (const [, y] of flat) assert.equal(y, flat[0][1], `line ${i} is flat past the ramp`);
    return flat[0][1];
  });
  const gaps = flatYs.slice(1).map((y, i) => y - flatYs[i]);
  for (const gap of gaps) assert.ok(gap > 0 && Math.abs(gap - gaps[0]) <= 0.11, 'the lines are evenly spaced');
});
